import { describe, expect, it } from 'vitest';
import { SttModels } from '@/lib/models';

/**
 * Model metadata is part of the download supply chain. An incorrect filename, size, or hash prevents first-time
 * setup, so these tests validate format and uniqueness without network access.
 */
describe('speech-recognition model metadata', () => {
  it('provides valid and unique integrity metadata for every model', () => {
    const filenames = new Set<string>();

    for (const model of SttModels) {
      expect(model.filename).toMatch(/^[a-z0-9][a-z0-9.-]*\.onnx$/);
      expect(model.size).toBeGreaterThan(0);
      expect(model.sha256).toMatch(/^[a-f0-9]{64}$/);
      expect(filenames.has(model.filename)).toBe(false);
      filenames.add(model.filename);
    }
  });
});

import { describe, expect, it } from 'vitest';
import { AIProviderType, TranscribeTaskStatus } from '@/lib/models';
import {
  normalizeConfigPatch,
  normalizeRecordingItems,
  normalizeTranscriptionTasks,
  isSafeLocalRecordId,
} from '@/lib/persistence/validation';

describe('persisted-data runtime validation', () => {
  it('safely falls back to empty collections for malformed top-level values', () => {
    expect(normalizeRecordingItems({ length: 1 })).toEqual([]);
    expect(normalizeTranscriptionTasks('invalid')).toEqual([]);
    expect(normalizeConfigPatch([])).toBeNull();
  });

  it('filters records without identifiers and restores recoverable recording fields', () => {
    const records = normalizeRecordingItems([
      { id: 'valid', createdAt: 10, result: 'text', segments: [{ text: 'text' }] },
      { id: 123, createdAt: 11 },
    ]);

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({ id: 'valid', aiContent: '', saveAudio: false, duration: 0 });
    expect(records[0]?.segments[0]).toMatchObject({ index: 0, start_ms: null, end_ms: null });
  });

  it('rejects history identifiers that could escape the recording directory', () => {
    expect(isSafeLocalRecordId('4f2a45b1-71fd-46ca-b114-a55045f87ae5')).toBe(true);
    expect(isSafeLocalRecordId('../outside')).toBe(false);
    expect(isSafeLocalRecordId('/tmp/outside')).toBe(false);
    expect(isSafeLocalRecordId('folder\\outside')).toBe(false);
    expect(isSafeLocalRecordId('a'.repeat(129))).toBe(false);

    expect(normalizeRecordingItems([{ id: '../outside', createdAt: 1, result: 'unsafe' }])).toEqual([]);
  });

  it('clamps progress and converts unknown task states to Error', () => {
    const tasks = normalizeTranscriptionTasks([
      { id: 'task', filePath: '/tmp/a.mp3', createdAt: 1, status: 'unknown', progress: 999 },
    ]);

    expect(tasks[0]?.status).toBe(TranscribeTaskStatus.Error);
    expect(tasks[0]?.progress).toBe(100);
  });

  it('accepts only supported configuration fields and clamps AI numeric values', () => {
    const patch = normalizeConfigPatch({
      record_mic: false,
      unexpected: 'ignored',
      keywords: ['FlashVoice', 123],
      aiCorrection: {
        provider: AIProviderType.Ollama,
        providers: [
          {
            provider: AIProviderType.Ollama,
            model: 'qwen3:4b',
            endpoint: 'http://localhost:11434/v1',
            temperature: 99,
            maxTokens: -10,
            timeout: 0,
          },
        ],
      },
    });

    expect(patch).not.toHaveProperty('unexpected');
    expect(patch?.keywords).toEqual(['FlashVoice']);
    const ollama = patch?.aiCorrection?.providers.find(item => item.provider === AIProviderType.Ollama);
    expect(ollama).toMatchObject({ temperature: 2, maxTokens: 0, timeout: 1 });
  });

  it('preserves user-selected model names without silent migration during configuration loading', () => {
    const patch = normalizeConfigPatch({
      aiCorrection: {
        providers: [
          { provider: AIProviderType.Kimi, model: 'kimi-latest' },
          { provider: AIProviderType.Google, model: 'gemini-3-pro-preview' },
          { provider: AIProviderType.Ollama, model: 'my-local-model:latest' },
        ],
      },
    });

    const providers = patch?.aiCorrection?.providers;
    expect(providers?.find(item => item.provider === AIProviderType.Kimi)?.model).toBe('kimi-latest');
    expect(providers?.find(item => item.provider === AIProviderType.Kimi)?.temperature).toBe(1);
    expect(providers?.find(item => item.provider === AIProviderType.Google)?.model).toBe('gemini-3-pro-preview');
